import assert from "node:assert/strict";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

import {
  managedSkillContents,
  managedSkillMetadataContents,
  projectPaths,
  setupProject,
} from "../src/project.js";

const SKILL_SOURCE = fileURLToPath(
  new URL("../agent-skill/attend-visualize/SKILL.md", import.meta.url),
);
const METADATA_SOURCE = fileURLToPath(
  new URL("../agent-skill/attend-visualize/agents/openai.yaml", import.meta.url),
);

async function fixture(t) {
  const root = await mkdtemp(join(tmpdir(), "attend-skill-bundle-"));
  t.after(() => rm(root, { recursive: true, force: true }));
  return root;
}

test("setup installs, audits, and repairs the complete managed skill bundle", async (t) => {
  const root = await fixture(t);
  const options = {
    root,
    skillSource: SKILL_SOURCE,
    skillMetadataSource: METADATA_SOURCE,
  };
  const installed = await setupProject(options);
  assert.ok(installed.created.includes(".agents/skills/attend-visualize/SKILL.md"));
  assert.ok(installed.created.includes(".agents/skills/attend-visualize/agents/openai.yaml"));
  assert.ok(installed.created.includes(".claude/skills/attend-visualize/SKILL.md"));

  const paths = projectPaths(root);
  assert.equal(
    await readFile(paths.skill, "utf8"),
    managedSkillContents(await readFile(SKILL_SOURCE, "utf8")),
  );
  const installedSkill = await readFile(paths.skill, "utf8");
  assert.match(installedSkill, /named visual (?:form|properties).*hard constraint/iu);
  assert.match(installedSkill, /unsupported proactive opportunit(?:y|ies).*silent/iu);
  assert.match(installedSkill, /explicit unsupported request.*defer/iu);
  assert.match(installedSkill, /primary lane is proactive exploratory data analysis/iu);
  assert.match(installedSkill, /ordinary just-in-time visualization workflow/iu);
  assert.match(installedSkill, /search the repository for an existing example, template, or prior implementation/iu);
  assert.match(installedSkill, /before setup, source inspection, exploration, compilation/iu);
  assert.match(installedSkill, /"representationIntent"/u);
  assert.equal(
    await readFile(paths.skillMetadata.path, "utf8"),
    managedSkillMetadataContents(await readFile(METADATA_SOURCE, "utf8")),
  );

  const repeated = await setupProject(options);
  assert.deepEqual(repeated.created, []);
  assert.deepEqual(repeated.updated, []);

  await writeFile(
    paths.skillMetadata.path,
    "# attend-managed: generated by Attend setup\ninterface:\n  display_name: stale\n",
  );
  const repaired = await setupProject(options);
  assert.deepEqual(repaired.updated, [
    ".agents/skills/attend-visualize/agents/openai.yaml",
  ]);
});

test("an unmarked metadata collision stops setup before partial skill writes", async (t) => {
  const root = await fixture(t);
  const paths = projectPaths(root);
  await setupProject({ root });
  await mkdir(join(root, ".agents", "skills", "attend-visualize", "agents"), {
    recursive: true,
  });
  await writeFile(paths.skillMetadata.path, "interface:\n  display_name: User owned\n");

  await assert.rejects(
    setupProject({
      root,
      skillSource: SKILL_SOURCE,
      skillMetadataSource: METADATA_SOURCE,
    }),
    (error) => error?.code === "UNMANAGED_FILE"
      && error.path === ".agents/skills/attend-visualize/agents/openai.yaml",
  );
});
